#ifdef GL_ES
precision mediump float;
#endif

#define PI 3.14159265359
#define TWO_PI 6.28318530718

float rectangle(vec2 st, vec2 o, vec2 d){
    vec2 bl = step(o,st);
    vec2 tr = step(1.0-o-d,1.0-st);
    return bl.x*bl.y*tr.x*tr.y;
}
mat2 rotate2d(float _angle){
    return mat2(cos(_angle),-sin(_angle),
                sin(_angle),cos(_angle));
}

float drawBG(vec2 st){
    float d = length( abs(st));    // distance field

    const float BG_RADIAL_WIDTH = 0.03;
    const float BG_SCALE = 5.0;
    const float BG_FADE_SCALE = 0.5;

    float zenCircles = fract(d * BG_SCALE);
    float bgRadius = smoothstep(
        BG_RADIAL_WIDTH, 
        BG_RADIAL_WIDTH-0.01, 
        zenCircles
    );
    return bgRadius * BG_FADE_SCALE;
}

float drawTracker(float angle){
    const float TRACKER_INTENSITY = 2.612;
    const float TRACKER_COVER_DISTANCE = -1.868;
    float pct = (-angle/PI) * TRACKER_INTENSITY + TRACKER_COVER_DISTANCE;
    pct = max(pct, 0.0);    // don't accidentally negate the bg
    return pct;
}

float drawTarget(vec2 st, float rotateRate){
    const float RAD = 0.015;
    vec2 point = vec2(0.0,0.5);
    float d = distance(point,st);

    float body = 1.0-step(RAD,d);
    float outline = step(RAD+0.005,d)*step(d,RAD+0.01);

    float blinkF = abs(sin(iTime*5.0));

    float x = iTime + PI*0.5;
    x = cos(x);
    float spikeF = 1.0/(1.0+20.0*x*x);
    float growF = cos(iTime)*0.3;
    growF = growF*spikeF;
    float growRing = 
        (1.0-step(growF, d))
        - (smoothstep(growF,growF-0.1,d));

    return clamp(1.0,0.0,body * blinkF + outline + growRing);
}

void mainImage( out vec4 fragColor, in vec2 fragCoord ) {
    ////// SETUP
    vec2 R = iResolution.xy;
    vec2 st = (fragCoord*2.-R.xy)/R.y;

    const float ROTATE_RATE = 0.3;
    vec2 rotatedST = st * rotate2d( (iTime * ROTATE_RATE) * PI );

    ////// VAR
    const vec3 BLUE = vec3(0.0,1.0,1.0);
    const vec3 RED = vec3(1.0,0.263,0.08);
    vec2 toCenter = vec2(0) - rotatedST;
    float angle = atan(toCenter.y,toCenter.x);

    vec3 color = vec3(0.0);

    ////// DRAW FUNCTIONS
    color += drawBG(st) * BLUE;
    color += drawTracker(angle) * BLUE;
    color += drawTarget(st, ROTATE_RATE) * RED;

    fragColor = vec4(color,1.0);
}
